from pathlib import Path
from typing import Generator


def walk_glob(
    root_directory: str | Path,
    pattern: str,
    max_depth: int | None = None,
) -> Generator[Path, None, None]:
    """
    Walk a directory tree and yield every file matching the glob pattern.

    Skips hidden directories and symlinks. Prevents infinite loops from
    symlinked directories by tracking visited inodes.

    Args:
        root_directory: Root directory to search
        pattern: Glob pattern to match (e.g., '*.txt', '**/*.py')
        max_depth: Maximum directory depth to traverse (None for unlimited)

    Yields:
        Path objects for each matching file
    """
    root = Path(root_directory).resolve()

    if not root.is_dir():
        return

    visited = set()

    def visit(directory: Path, depth: int):
        if max_depth is not None and depth > max_depth:
            return

        try:
            stat = directory.stat()
            inode_key = (stat.st_dev, stat.st_ino)
            if inode_key in visited:
                return
            visited.add(inode_key)
        except (OSError, ValueError):
            return

        if any(part.startswith('.') for part in directory.parts):
            return

        try:
            for entry in directory.iterdir():
                if entry.is_symlink():
                    continue

                if entry.is_file() and entry.match(pattern):
                    yield entry
                elif entry.is_dir():
                    yield from visit(entry, depth + 1)
        except (OSError, PermissionError):
            pass

    yield from visit(root, 0)


def walk_glob_list(
    root_directory: str | Path,
    pattern: str,
    max_depth: int | None = None,
) -> list[Path]:
    """Return all matching files as a sorted list."""
    return sorted(walk_glob(root_directory, pattern, max_depth))
